def check_golomb(ruler):
    diffs = set()
    for i in range(len(ruler)):
        for j in range(i+1, len(ruler)):
            diff = ruler[j] - ruler[i]
            if diff in diffs:
                return False
            diffs.add(diff)
    return True

print(check_golomb([0, 1, 4, 9, 11]))
print(check_golomb([0, 2, 7, 8, 11]))
